/**
 * Wire model for the platform's polymorphic `AgenticSkillTool`
 * GraphQL interface, surfaced through antman's `getSkill` endpoint
 * (`antman/.../skill/SkillClient.java`'s GraphQL fragment).
 *
 * Mirrors antman's flat-union `SkillTool` Java record: every
 * variant-specific field is optional on the wire, populated based on
 * `type`. Same convention as the canonical agent-tool model. Antman
 * aliases the platform's `__typename` to `type` so the GraphQL-y
 * field name doesn't leak into the REST surface; it also aliases the
 * platform's coarser `type` scalar to `category` to avoid colliding
 * with the variant discriminator above.
 */
/**
 * Closed set of `SkillTool` variants the EDK round-trips. Mirrors
 * the platform's `AgenticSkillTool` union discriminators.
 */
export type SkillToolType = "AgenticSkillAutomationTool" | "AgenticSkillSearchAspectTool" | "AgenticSkillSearchTableTool" | "AgenticSkillCreateRecordTool" | "AgenticSkillUpdateRecordTool" | "AgenticSkillRunAgentTool";
/**
 * One field entry on a skill tool's `fields[]` array — covers the
 * search-side and record-side variants. `required` and `defaultValue`
 * are populated only on the create/update variants.
 *
 * The field reference itself appears in two shapes depending on the
 * read path: `GET /v1/skills/{id}` (antman's REST facade over the
 * graph) nests it the same way agent tools do — `field: { id, ... }`,
 * with every other property on that nested object left `null` — while
 * some callers still send/expect the flatter `fieldId` UUID. Both are
 * optional here so a reader can fall back (`fieldId ?? field?.id`)
 * regardless of which shape actually arrived; don't assume either is
 * exclusively present.
 */
export interface SkillToolField {
    readonly fieldId?: string;
    readonly field?: {
        readonly id: string;
    };
    readonly name?: string;
    readonly description?: string;
    readonly required?: boolean;
    readonly defaultValue?: string;
}
/**
 * Filter variable carried on search variants — `{ name, value }`
 * pair. The EDK builder doesn't surface these today; pulled skills
 * with non-empty `filterVariables` drop the variable list with a
 * structured miss.
 */
export interface SkillToolFilterVariable {
    readonly name: string;
    readonly value: string;
}
/**
 * Polymorphic skill-tool wire shape. `type` is the discriminator;
 * only the fields a given variant supplies are populated. Every
 * variant carries the shared identity bookkeeping (`id`, `name`,
 * `description`, `status`, `startMessage`).
 *
 * Variant-to-fields map (every field optional, populated per `type`):
 *
 * | type                            | extra fields                                                       |
 * |---------------------------------|--------------------------------------------------------------------|
 * | AgenticSkillAutomationTool      | automation                                                         |
 * | AgenticSkillSearchAspectTool    | aspect, fields, filter, filterVariables, sort, limit, queryDescription |
 * | AgenticSkillSearchTableTool     | aspect, table, fields, filter, filterVariables, limit, queryDescription |
 * | AgenticSkillCreateRecordTool    | aspect, fields                                                     |
 * | AgenticSkillUpdateRecordTool    | aspect, fields, handleDescription                                  |
 * | AgenticSkillRunAgentTool        | targetAgent, workerTaskPrompt                                      |
 *
 * `filter` / `sort` / `limit` / `filterVariables` aren't authored by
 * the EDK skill builder today — the deserializer drops them with a
 * structured miss when they're non-empty so the pulled source stays
 * within what the builder can re-emit.
 *
 * Note: `aspect.__typename` retains the GraphQL-y name because the
 * apps/aspect wire surface still uses `__typename`; antman doesn't
 * rename it across the skill query either.
 */
export interface SkillTool {
    readonly type?: SkillToolType;
    readonly id: string;
    readonly name: string;
    readonly description: string;
    readonly status?: string;
    readonly startMessage?: string;
    /**
     * Coarser tool-type scalar — aliased from the platform's `type`
     * field via GraphQL so it doesn't collide with the variant
     * discriminator. Informational only; the EDK doesn't author it.
     */
    readonly category?: string;
    readonly automation?: {
        readonly id: string;
        readonly name?: string;
    };
    readonly aspect?: {
        readonly id: string;
        readonly __typename?: string;
        readonly name?: string;
    };
    readonly table?: {
        readonly id: string;
        readonly displayName?: string;
    };
    readonly fields?: readonly SkillToolField[];
    readonly filter?: import("../../../../src/entities/shared/filters/types.js").Filter;
    readonly filterVariables?: readonly SkillToolFilterVariable[];
    readonly sort?: {
        readonly orders: ReadonlyArray<{
            readonly field: string;
            readonly direction: "ASC" | "DESC";
        }>;
    };
    readonly limit?: number;
    readonly queryDescription?: string;
    readonly handleDescription?: string;
    readonly targetAgent?: {
        readonly id: string;
        readonly name?: string;
        readonly type?: string;
    };
    readonly workerTaskPrompt?: string;
}
